using Westworld.Runtime.Core;
using Westworld.Scapi.Adapter;
int checks=0; void Check(bool b,string s){checks++;if(!b)throw new Exception(s);}
var cells=new List<CellObservation>();for(int x=-4;x<=4;x++)for(int z=-4;z<=4;z++)for(int y=63;y<=65;y++)cells.Add(new(x,y,z,"known",y==63?2:0));
var o=new ActorObservation(Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),10,new(.5,64,.5),1,.5f,[],cells.ToArray());
var r=LocalRouteCandidates.Project(o);Check(r.Candidates.Count==8,"flat eight");Check(r.Evidence.Count==8,"proof per candidate");Check(r.ObservationId==o.ObservationId,"observation binding");
Check(r.Candidates.All(c=>c.KnownSafe&&r.Evidence[c.EvidenceId].All(e=>e.Visibility=="known"&&e.Value.HasValue)),"proof only known");
ActorObservation Ground(int? value,string visibility="known")=>o with {Cells=o.Cells.Select(c=>c.Y==63?c with{Value=value,Visibility=visibility}:c).ToArray()};
Check(LocalRouteCandidates.Project(Ground(0)).Candidates.Count==0,"cliff");
Check(LocalRouteCandidates.Project(Ground(18)).Candidates.Count==0,"water");
Check(LocalRouteCandidates.Project(Ground(7)).Candidates.Count==0,"default strict policy rejects falling sand");
Check(LocalRouteCandidates.Project(Ground(null,"unknown")).Candidates.Count==0,"unknown ground");
Check(LocalRouteCandidates.Project(o with{Cells=o.Cells.Where(c=>c.Y!=65).ToArray()}).Candidates.Count==0,"missing head clearance");
Check(LocalRouteCandidates.Project(o with{Cells=o.Cells.Select(c=>c.Y==64?c with{Value=3}:c).ToArray()}).Candidates.Count==0,"blocked body");
Check(LocalRouteCandidates.Project(o with{Position=new(.5,64.4,.5)}).Candidates.Count==0,"midair height");
Check(LocalRouteCandidates.Project(o with{Position=new(double.NaN,64,.5)}).Candidates.Count==0,"nan");
Check(LocalRouteCandidates.Project(o with{Cells=o.Cells.Concat(new[]{o.Cells[0]}).ToArray()}).Candidates.Count==0,"duplicate provenance");
Check(LocalRouteCandidates.Project(o with{ObservationId=Guid.Empty}).Candidates.Count==0,"missing observation id");
Check(LocalRouteCandidates.Project(o,2).Candidates.Count==8,"two metre bounded");
bool bad=false;try{LocalRouteCandidates.Project(o,2.1);}catch(ArgumentOutOfRangeException){bad=true;}Check(bad,"reject range");
Check(LocalRouteCandidates.Project(o with{Cells=o.Cells.Select(c=>c.X==1&&c.Y==63?c with{Value=0}:c).ToArray()}).Candidates.All(c=>c.Destination.X<=o.Position.X),"swept gap rejects whole route");
// Mimic a forward-only eye snapshot: the occupied start column is not inferred.
var partial=o with{Cells=o.Cells.Select(c=>c.Z<=0?c with{Visibility="unknown",Value=null}:c).ToArray()};
Check(LocalRouteCandidates.Project(partial).Candidates.Count==0,"forward cone cannot manufacture unseen feet/ground");
Check(LocalRouteCandidates.Project(o with{Position=new(10_000_001,64,.5)}).Candidates.Count==0,"outside world envelope");
Check(LocalRouteCandidates.Project(o with{Position=new(.5,255,.5)}).Candidates.Count==0,"ceiling envelope");
Check(r.Candidates.All(c=>r.Evidence[c.EvidenceId].All(e=>o.Cells.Contains(e))),"evidence comes only from input snapshot");
Check(r.Candidates.Select(c=>((int)Math.Floor(c.Destination.X),(int)Math.Floor(c.Destination.Z))).Distinct().Count()==r.Candidates.Count,"unique destination cells");
var sand = LocalRouteCandidates.Project(Ground(7), groundPolicy: RouteGroundPolicy.ObservedFullCube);
Check(sand.Candidates.Count==8,"explicit observed cube policy permits observed sand");
Check(sand.GroundPolicy==RouteGroundPolicy.ObservedFullCube,"policy recorded with evidence");
Check(LocalRouteCandidates.Project(Ground(6), groundPolicy: RouteGroundPolicy.ObservedFullCube).Candidates.Count==8,"observed gravel");
Check(LocalRouteCandidates.Project(Ground(6)).Candidates.Count==0,"strict gravel rejected");
Check(LocalRouteCandidates.Project(Ground(18), groundPolicy: RouteGroundPolicy.ObservedFullCube).Candidates.Count==0,"relaxed policy still rejects water");
Check(LocalRouteCandidates.Project(Ground(0), groundPolicy: RouteGroundPolicy.ObservedFullCube).Candidates.Count==0,"relaxed policy still rejects cliff");
Check(LocalRouteCandidates.Project(Ground(null,"unknown"), groundPolicy: RouteGroundPolicy.ObservedFullCube).Candidates.Count==0,"relaxed policy still rejects unknown");
Check(sand.Evidence.Values.All(es=>es.All(e=>e.Y>=63)),"no inferred subfloor support");
bool badPolicy=false;try{LocalRouteCandidates.Project(o,groundPolicy:(RouteGroundPolicy)99);}catch(ArgumentOutOfRangeException){badPolicy=true;}Check(badPolicy,"invalid ground policy");
// Native half-width .25: centre x=.75 just touches the wall starting at x=1.
var touching=o with{Position=new(.75,64,.5),Cells=o.Cells.Select(c=>c.X>=1&&c.Y>=64?c with{Value=3}:c).ToArray()};
var touchRoutes=LocalRouteCandidates.Project(touching);
Check(touchRoutes.Candidates.Any(c=>Math.Abs(c.Destination.X-.75)<1e-8&&c.Destination.Z>1),"wall-parallel positive route allowed");
Check(touchRoutes.Candidates.Any(c=>Math.Abs(c.Destination.X-.75)<1e-8&&c.Destination.Z<0),"wall-parallel negative route allowed");
Check(touchRoutes.Candidates.Any(c=>c.Destination.X<.75),"move away from wall allowed");
Check(touchRoutes.Candidates.All(c=>c.Destination.X<=.75),"move into wall rejected");
Check(touchRoutes.Evidence.Values.All(es=>es.Where(e=>e.Y>=64).All(e=>e.X<1)),"contact wall is not claimed as air");
Check(LocalRouteCandidates.Project(touching with{Position=new(.75+1e-6,64,.5)}).Candidates.Count==touchRoutes.Candidates.Count,"tiny contact rounding tolerated");
Check(LocalRouteCandidates.Project(touching with{Position=new(.75+2e-5,64,.5)}).Candidates.Count==0,"real penetration is not contact");
var touchingLower=o with{Position=new(.25,64,.5),Cells=o.Cells.Select(c=>c.X<0&&c.Y>=64?c with{Value=3}:c).ToArray()};
Check(LocalRouteCandidates.Project(touchingLower).Candidates.Any(c=>c.Destination.X>.25),"lower boundary departure allowed");
Check(LocalRouteCandidates.Project(touchingLower).Candidates.All(c=>c.Destination.X>=.25),"lower boundary entry rejected");
var unknownWall=touching with{Cells=touching.Cells.Select(c=>c.X==0&&c.Y==64?c with{Visibility="unknown",Value=null}:c).ToArray()};
Check(LocalRouteCandidates.Project(unknownWall).Candidates.Count==0,"actual occupied start column still requires known air");
Console.WriteLine($"{checks}/{checks} synthetic snapshot projection assertions passed; no live world tested");
